      appState.pending={type:'target_selection', decision_side:'PLAYER', source_side:null, source_lane:null, card_id:cardId, hand_index:index, target_side:targetSideForActor(c,'PLAYER'), legal_targets:legalTargetLanesFor(appState,'PLAYER',cardId,null)};
      pushLog(appState,'Choose target for '+cardName(c)+'.'); render(); return;
