    if(st){ var sr=[st.remaining_turns,st.turns_remaining,st.duration,st.remaining].find(function(v){ return typeof v!=='undefined' && v!==null && Number(v)>0; }); if(typeof sr!=='undefined') return '('+Number(sr)+')'; }
