      s.playerHeroes.RIGHT.card_id='S1-WAR-H004'; s.playerHeroes.RIGHT.hp=90; s.playerHeroes.RIGHT.statuses=[];
      openAttackResponseWindow(s,{card_id:'S1-MAG-001',source_side:'AI',source_lane:'CENTER',target_side:'PLAYER',target_lane:'CENTER'},{damage:20,persistent:false,attachmentSlot:-1});
