      s.turn='PLAYER'; s.phase='Deploy'; s.mana=10; s.playerHand=['S1-CLE-004'];
      s.playerHeroes.RIGHT.card_id='S1-CLE-H005'; s.playerHeroes.RIGHT.hp=110; s.playerHeroes.RIGHT.maxHp=110; s.playerHeroes.RIGHT.exhausted=false;
