      addStatus(s.playerHeroes.LEFT,'Bleed',2,'Bleed test');
      if(!legalPlayState(s,'S1-CLE-004').can) return {ok:false, reason:'Purify not legal with Bleed target', state:s};
      beginPlayFromHand(0); chooseHeroFromBoard('PLAYER','RIGHT');
      if(!s.pending || s.pending.type!=='target_selection' || s.pending.legal_targets.indexOf('LEFT')===-1) return {ok:false, reason:'Purify target validator did not include Bleed target', pending:s.pending};
      chooseHeroFromBoard('PLAYER','LEFT');
      if(hasStatus(s.playerHeroes.LEFT,'Bleed')) return {ok:false, reason:'Purify did not remove Bleed', statuses:s.playerHeroes.LEFT.statuses};

      // Legacy Mode is not a legal Attack target and all-Legacy side loses.
