      LANE_ORDER.forEach(function(l){ s.aiHeroes[l].card_id='S1-WAR-L001'; s.aiHeroes[l].legacy_mode=true; s.aiHeroes[l].hp=1; s.aiHeroes[l].maxHp=1; });
      if(legalTargetLanesFor(s,'PLAYER','S1-WAR-001','CENTER').length) return {ok:false, reason:'Legacy appeared as legal attack target'};
      checkGameEnd(s);
      if(!s.gameOver || s.winner!=='PLAYER' || s.gameResultShown!==false) return {ok:false, reason:'All-Legacy opponent did not trigger game end', state:s};

      // Manual Reposition should still be available for adjacent board units when a Legacy is on the field.
