      s.playerHeroes.LEFT.card_id='S1-WAR-L001'; s.playerHeroes.LEFT.legacy_mode=true; s.playerHeroes.LEFT.hp=1; s.playerHeroes.LEFT.maxHp=1; s.playerHeroes.LEFT.exhausted=false;
