      var defender=s.playerHeroes.CENTER;defender.card_id='S1-WAR-H001';defender.hp=100;defender.maxHp=100;defender.statuses=[];defender.attachments=[null,null];
      registerLocalAttachment(s,'PLAYER','CENTER',0,'S1-WAR-020',{tick_phase:'DRAW_PHASE_START',remaining_count:2,counter_mode:'countdown',role:'defense_reduction'},{commit_token:'QA:SHIELD_BASH'});
      if((defender.statuses||[]).length!==0) return {ok:false,reason:'Shield Bash created a duplicate Hero status badge',statuses:defender.statuses};
      var physical=applyResolvedAttackDamage(s,'S1-WAR-001','AI','CENTER','PLAYER','CENTER',30,'Physical',false,0);
      if(physical.active_reduction!==20||physical.damage!==10||Number(defender.hp)!==90) return {ok:false,reason:'Shield Bash Attachment did not directly reduce Physical damage',result:physical,hp:defender.hp};
      defender.hp=100;
