      if(magical.active_reduction!==0||magical.response_block!==40||magical.damage!==30||Number(defender.hp)!==70) return {ok:false,reason:'Shield Bash incorrectly reduced Magical damage or Dragon Scale math changed',result:magical,hp:defender.hp};

      // Counter is owned by activeAttachments and expires at its registered checkpoint.
      s.phase='Draw';s.turn='PLAYER';s.round=2;
      removeStartOfTurnTargetPreventionForSide(s,'PLAYER');
      var live=activeAttachmentForHero(s,defender,'S1-WAR-020');
      if(!live||Number(live.remaining_count)!==1) return {ok:false,reason:'Attachment counter did not decrement 2 to 1 at DRAW_PHASE_START',attachment:live,active:s.activeAttachments};
      if((defender.statuses||[]).length!==0) return {ok:false,reason:'Counter tick recreated a duplicate Hero status badge',statuses:defender.statuses};
      s.round=3;removeStartOfTurnTargetPreventionForSide(s,'PLAYER');
