      var victim=s.playerHeroes.CENTER;victim.hp=30;victim.maxHp=Math.max(30,Number(victim.maxHp||100));victim.statuses=[];victim.attachments=[null,null];
      var candidates=eligibleLegacyCardIdsForDefeatedHero(s,'PLAYER','CENTER',victim);
      if(!candidates.length) return {ok:false,reason:'QA victim has no Legacy replacement candidate',victim:victim,legacy:s.playerLegacy};
      var action={card_id:'S1-MAG-001',source_side:'AI',source_lane:'CENTER',target_side:'PLAYER',target_lane:'CENTER',commit_token:'QA:LETHAL_RESPONSE'};
      s.aiControl={resume:'after_player_response',from_phase:'Battle',director:false};
      openAttackResponseWindow(s,action,{damage:70,persistent:false,attachmentSlot:-1});
      if(!s.pending||s.pending.type!=='response_window') return {ok:false,reason:'Lethal response QA did not open response frame',pending:s.pending,response:s.responseWindow};
      resolveResponseWindow(null);
      if(!s.pending||s.pending.type!=='legacy_defeat_choice') return {ok:false,reason:'Defeated Hero did not open Legacy choice after response resolution',pending:s.pending,queue:s.legacyDefeatQueue,hero:s.playerHeroes.CENTER};
