  function simulateV1410DefeatReviveExpClearAudit(){
    initCards();
    var oldApp=appState,oldMatch=matchStarted,oldSuppress=SUPPRESS_RENDER,oldShuffle=STARTUP_SHUFFLE_ENABLED;
    SUPPRESS_RENDER=true;matchStarted=true;STARTUP_SHUFFLE_ENABLED=false;
    try{
      // Confirmed defeat clears EXP immediately, moves each EXP card to Discard exactly once,
      // and stores an empty-EXP defeated snapshot for Legacy Mode.
      var s=buildInitialMatchState();appState=s;s.pvpHumanVsHuman=true;
      var h=s.playerHeroes.LEFT;h.card_id='S1-WAR-H001';h.hp=0;h.exp_cards=['S1-WAR-001','S1-WAR-002'];h.exp_total=200;
      h.assigned_legacy_card_id='S1-WAR-L001';h.legacy_lineage_id='WAR-CONQUEROR';h.legacy_package_id='LEFT-PACKAGE';
      s.playerLegacy=['S1-WAR-L001'];s.playerLegacyPackageSlots=[{slot:'LEFT',package_id:'LEFT-PACKAGE',legacy:'S1-WAR-L001',progression:'S1-WAR-H001'}];
      if(!applyDefeatCheck(s,'PLAYER','LEFT')||!s.pending||s.pending.type!=='legacy_defeat_choice') return {ok:false,reason:'Defeat did not open Legacy choice',pending:s.pending};
      if(Number(h.exp_total||0)!==0||(h.exp_cards||[]).length) return {ok:false,reason:'Hero EXP was not cleared immediately on defeat',hero:h};
      if(s.playerDiscard.filter(function(id){return id==='S1-WAR-001';}).length!==1||s.playerDiscard.filter(function(id){return id==='S1-WAR-002';}).length!==1) return {ok:false,reason:'Defeated Hero EXP cards did not move to Discard exactly once',discard:s.playerDiscard};
      selectLegacyDefeatChoice(0);if(!commitLegacyDefeatChoice()) return {ok:false,reason:'Legacy replacement could not commit'};
      var legacy=s.playerHeroes.LEFT,snap=legacy.defeated_hero_snapshot||{};
      if(!isLegacyModeHero(legacy)||Number(snap.exp_total||0)!==0||(snap.exp_cards||[]).length) return {ok:false,reason:'Legacy defeated snapshot retained EXP',legacy:legacy};

      // Every revive source restores the Hero with empty EXP, not only Resurrection.
      if(!restoreHeroFromLegacyMode(s,'PLAYER','LEFT',10,'Phoenix Feather')) return {ok:false,reason:'Legacy revive failed'};
      h=s.playerHeroes.LEFT;
      if(h.hp!==10||Number(h.exp_total||0)!==0||(h.exp_cards||[]).length) return {ok:false,reason:'Revived Hero did not return with empty EXP',hero:h};

      // Direct defeated-Hero revive fallback is also empty-EXP and exact-once for older/custom states.
      s=buildInitialMatchState();appState=s;s.turn='PLAYER';s.phase='Deploy';s.mana=20;
      h=s.playerHeroes.LEFT;h.hp=0;h.exp_cards=['S1-WAR-001'];h.exp_total=100;s.playerHand=['S1-ITM-008'];
      beginPlayFromHand(0);chooseHeroFromBoard('PLAYER','LEFT');
      if(h.hp!==10||Number(h.exp_total||0)!==0||(h.exp_cards||[]).length||s.playerDiscard.filter(function(id){return id==='S1-WAR-001';}).length!==1) return {ok:false,reason:'Direct Phoenix Feather revive retained EXP or duplicated movement',hero:h,discard:s.playerDiscard};

      // The third/final Hero also clears EXP before the game-over state is committed.
      s=buildInitialMatchState();appState=s;s.playerHeroes.LEFT=transitionDefeatedHeroToLegacyMode(s,'PLAYER','LEFT','S1-WAR-L001',s.playerHeroes.LEFT)||s.playerHeroes.LEFT;s.playerHeroes.RIGHT=transitionDefeatedHeroToLegacyMode(s,'PLAYER','RIGHT','S1-THF-L001',s.playerHeroes.RIGHT)||s.playerHeroes.RIGHT;
      h=s.playerHeroes.CENTER;h.hp=0;h.exp_cards=['S1-WAR-002'];h.exp_total=100;applyDefeatCheck(s,'PLAYER','CENTER');
      if(Number(h.exp_total||0)!==0||(h.exp_cards||[]).length||s.playerDiscard.filter(function(id){return id==='S1-WAR-002';}).length!==1) return {ok:false,reason:'Final defeated Hero retained EXP',hero:h,discard:s.playerDiscard};

      return {ok:true,version:'v1.41.0',defeatExpZero:true,legacySnapshotExpZero:true,allRevivesExpZero:true,finalHeroExpZero:true,expDiscardExactlyOnce:true};
    }catch(e){return {ok:false,error:String(e&&e.stack||e)};}
    finally{appState=oldApp;matchStarted=oldMatch;SUPPRESS_RENDER=oldSuppress;STARTUP_SHUFFLE_ENABLED=oldShuffle;closeChoice();closeResponseWindowUI();}
  }
  window.GL_V1410_EXP_CLEAR_QA_SELF_TEST=simulateV1410DefeatReviveExpClearAudit;



