      resolveResponseWindow(null);
      if(s.aiHeroes.LEFT.hp!==afterFirst||!(s.aiHeroes.CENTER.hp<centerBeforeRank2)) return {ok:false,reason:'Elementalist Double Casting different target did not resolve independently',leftAfterFirst:afterFirst,leftAfterSecond:s.aiHeroes.LEFT.hp,centerBefore:centerBeforeRank2,centerAfter:s.aiHeroes.CENTER.hp};
      if(hasDoubleCasting(s.playerHeroes.LEFT)) return {ok:false,reason:'Double Casting Attachment was not consumed after activation 2/2'};

      s=freshDoubleCastingState('S1-MAG-H003',true); var leftBefore=s.aiHeroes.LEFT.hp, centerBefore=s.aiHeroes.CENTER.hp;
      commitPlayedCard(s,{card_id:'S1-MAG-003',hand_index:0,source_side:'PLAYER',source_lane:'LEFT',target_side:'AI',target_lane:'LEFT'});
      resolveResponseWindow(null);
      var leftAfterFirst=s.aiHeroes.LEFT.hp;
      if(!(leftAfterFirst<leftBefore)) return {ok:false,reason:'Different-target activation 1/2 did not damage target 1',before:leftBefore,after:leftAfterFirst};
      if(!s.pending||s.pending.type!=='double_casting_target_selection') return {ok:false,reason:'Different-target Double Casting selection missing'};
      commitDoubleCastingSecondTarget(s,s.pending,'CENTER');
      if(!s.responseWindow) return {ok:false,reason:'Different-target activation 2/2 Response Window missing'};
      resolveResponseWindow(null);
      if(s.aiHeroes.LEFT.hp!==leftAfterFirst||!(s.aiHeroes.CENTER.hp<centerBefore)) return {ok:false,reason:'Double Casting different targets did not resolve independently',leftBefore:leftBefore,leftAfterFirst:leftAfterFirst,leftAfterSecond:s.aiHeroes.LEFT.hp,centerBefore:centerBefore,centerAfter:s.aiHeroes.CENTER.hp};

      s=freshDoubleCastingState('S1-MAG-H003',true);
      s.aiHeroes.LEFT=heroState('S1-WAR-H001','AI','LEFT'); s.aiHeroes.LEFT.hp=20; s.aiHeroes.LEFT.maxHp=80; s.aiHeroes.LEFT.assigned_legacy_card_id='S1-WAR-L001';
      s.aiLegacy=['S1-WAR-L001']; s.aiHeroes.CENTER.hp=100; centerBefore=s.aiHeroes.CENTER.hp;
